n:absolute;right:10px;top:9px;background:#17181bcc;border:1px solid #4a4c50;padding:7px 9px;border-radius:5px;color:#aaa;pointer-events:none}.inspector{padding:10px}.field{margin:8px 0}.field label{display:block;color:#999;font-size:10px;margin-bottom:4px}.field input,.field select{width:100%;height:28px;background:#151619;border:1px solid #3a3d42;color:#eee;border-radius:4px;padding:0 6px}.trip{display:grid;grid-template-columns:1fr 1fr 1fr;gap:5px}.tabs{display:flex;border-bottom:1px solid #38393d}.tabs button{border:0;border-radius:0;background:none;padding:10px;flex:1;color:#aaa}.tabs .on{color:#fff;border-bottom:2px solid #79b8ff}.timeline{background:#1d1f22;border-top:1px solid #3a3b3f;display:grid;grid-template-columns:180px 1fr;min-height:145px;max-height:145px}.tracks{border-right:1px solid #3a3b3f}.trackhead{height:29px;padding:8px;color:#aaa;border-bottom:1px solid #34363a}.track{height:27px;padding:7px 9px;border-bottom:1px solid #303236}.sheet{position:relative;overflow:hidden;background:repeating-linear-gradient(90deg,#1d1f22 0,#1d1f22 39px,#282a2e 40px)}.numbers{height:29px;border-bottom:1px solid #34363a;color:#888;display:flex}.numbers span{width:40px;text-align:center;padding-top:8px}.key{position:absolute;width:7px;height:7px;background:#f0b65d;transform:rotate(45deg);top:37px}.playhead{position:absolute;top:0;bottom:0;width:1px;background:#ff6675;left:12px}.bottom{display:flex;align-items:center;justify-content:space-between;padding:0 9px;background:#202125;border-top:1px solid #38393d;color:#888;font-size:10px}.pill{padding:3px 6px;border:1px solid #3a3d42;border-radius:10px;margin-right:3px}.drop{border:1px dashed #4b4e54;padding:13px;text-align:center;color:#888;border-radius:5px}.file{display:none}.wide{grid-column:1/-1}.primary{background:#365b7e;border-color:#5e8eb9}.danger{color:#ef8d95}.muted{color:#888;font-size:10px;line-height:1.5}@media(max-width:900px){.main{grid-template-columns:50px 175px minmax(0,1fr)}.right{display:none}.cmd{max-width:none}}
