<script type="importmap">{"imports":{"three":"https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js","three/addons/":"https://cdn.jsdelivr.net/npm/three@0.180.0/examples/jsm/"}}</script>
<script type="module">
import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {TransformControls} from 'three/addons/controls/TransformControls.js';
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';
import {RGBELoader} from 'three/addons/loaders/RGBELoader.js';
const el=id=>document.getElementById(id), host=el('canvas');
const scene=new THREE.Scene();scene.background=new THREE.Color(0x303236);
const camera=new THREE.PerspectiveCamera(48,1,.05,1000);camera.position.set(11,7,14);
const renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.shadowMap.enabled=true;host.appendChild(renderer.domElement);
const orbit=new OrbitControls(camera,renderer.domElement);orbit.enableDamping=true;orbit.target.set(0,2,0);
const tc=new TransformControls(camera,renderer.domElement);scene.add(tc.getHelper());tc.addEventListener('dragging-changed',e=>orbit.enabled=!e.value);
scene.add(new THREE.GridHelper(60,60,0x55585e,0x3b3e43));
scene.add(new THREE.HemisphereLight(0xdce8ff,0x40453d,2.1));const sun=new THREE.DirectionalLight(0xffffff,3);sun.position.set(10,18,8);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);
const world=new THREE.Group();world.name='World';scene.add(world);const objs=[];let selected=null;let count=1;
const M=c=>new THREE.MeshStandardMaterial({color:c,roughness:.8});function part(g,geo,m,p=[0,0,0],s=[1,1,1]){let x=new THREE.Mesh(geo,m);x.position.set(...p);x.scale.set(...s);x.castShadow=x.receiveShadow=true;g.add(x);return x}
function add(g,name){g.name=name||'Object '+count++;g.userData.editable=true;world.add(g);objs.push(g);pick(g);ui();return g}
function human(k){let g=new THREE.Group(),body=M(k==='woman'?0x874c91:k==='child'?0xc47b3d:0x386fa6),skin=M(0xb87355);part(g,new THREE.CapsuleGeometry(.55,1.4,7,16),body,[0,2.5,0]);part(g,new THREE.SphereGeometry(.47,24,16),skin,[0,4.05,0]);for(let x of[-.68,.68]){part(g,new THREE.CapsuleGeometry(.14,1.2,6,10),body,[x,2.55,0]);part(g,new THREE.CapsuleGeometry(.17,1.5,6,10),M(0x25282d),[x,1,0])}return add(g,k[0].toUpperCase()+k.slice(1))}
function animal(k){let g=new THREE.Group(),m=M(k==='dog'?0x825a3d:k==='cat'?0xaaa09a:0x8b6b4d);part(g,new THREE.SphereGeometry(1,20,14),m,[0,1.15,0],[1.35,.75,.75]);part(g,new THREE.SphereGeometry(.52,20,14),m,[0,1.85,-.9]);for(let x of[-.65,.65])for(let z of[-.35,.35])part(g,new THREE.CapsuleGeometry(.12,.7,5,8),m,[x,.55,z]);return add(g,k[0].toUpperCase()+k.slice(1))}
function tree(k='tree'){let g=new THREE.Group();part(g,new THREE.CylinderGeometry(.28,.45,3.1,14),M(0x6a4932),[0,1.55,0]);part(g,k==='pine'?new THREE.ConeGeometry(1.5,4,18):new THREE.SphereGeometry(1.6,20,14),M(k==='pine'?0x2f6940:0x3b7d47),[0,3.9,0]);return add(g,k==='pine'?'Pine':'Tree')}
function rock(){let g=new THREE.Group();part(g,new THREE.DodecahedronGeometry(1.25,1),M(0x777978),[0,.9,0],[1.5,.8,1]);return add(g,'Rock')}
function mountain(){let g=new THREE.Group();[[-7,8,-8],[-2,11,-10],[4,9,-8],[9,7,-11]].forEach(a=>{part(g,new THREE.ConeGeometry(5,a[1],7),M(0x59636a),[a[0],a[1]/2,a[2]]);part(g,new THREE.ConeGeometry(1.8,2.5,7),M(0xe1e5e8),[a[0],a[1]-1,a[2]])});return add(g,'Mountain Range')}
function car(){let g=new THREE.Group();part(g,new THREE.BoxGeometry(4.3,.8,1.8),M(0x9b3438),[0,1,0]);part(g,new THREE.BoxGeometry(2,.75,1.5),M(0x202a34),[.2,1.7,0]);for(let x of[-1.35,1.35])for(let z of[-1,1])part(g,new THREE.CylinderGeometry(.43,.43,.28,24),M(0x17191d),[x,.5,z]);return add(g,'Car')}
function house(){let g=new THREE.Group();part(g,new THREE.BoxGeometry(5,3.3,4),M(0xc5a47b),[0,1.65,0]);let r=part(g,new THREE.ConeGeometry(3.5,2.2,4),M(0x684036),[0,4.35,0]);r.rotation.y=Math.PI/4;return add(g,'House')}
function chair(){let g=new THREE.Group();for(let x of[-.45,.45])for(let z of[-.45,.45])part(g,new THREE.BoxGeometry(.16,1.5,.16),M(0x7b563d),[x,.75,z]);part(g,new THREE.BoxGeometry(1.1,.18,1.1),M(0x7b563d),[0,1.5,0]);part(g,new THREE.BoxGeometry(1.1,1.25,.18),M(0x7b563d),[0,2.1,.46]);return add(g,'Chair')}
function camp(){let g=new THREE.Group();part(g,new THREE.ConeGeometry(1.8,2.4,4),M(0xb29d6c),[0,1.2,0]);return add(g,'Tent')}
const maker={man:()=>human('man'),woman:()=>human('woman'),child:()=>human('child'),character:()=>human('man'),dog:()=>animal('dog'),cat:()=>animal('cat'),horse:()=>animal('horse'),bird:()=>animal('bird'),tree:()=>tree(),pine:()=>tree('pine'),rock,mountain,car,house,chair,camp};
function ground(c){let m=new THREE.Mesh(new THREE.PlaneGeometry(70,70),M(c));m.rotation.x=-Math.PI/2;m.receiveShadow=true;world.add(m)}
function clear(){objs.forEach(o=>world.remove(o));objs.length=0;selected=null;tc.detach()}
function location(k){clear();ground({mountain:0x4e5b50,forest:0x3d7045,beach:0xc3ae78,desert:0xc48e61,city:0x51545a,village:0x667a60}[k]||0x505550);if(k==='mountain')mountain();if(k==='forest')for(let x=-12;x<=12;x+=4)for(let z=-10;z<=2;z+=5){let t=tree(Math.random()>.7?'pine':'tree');t.position.set(x+(Math.random()-.5)*2,0,z)}if(k==='village')for(let x=-8;x<=8;x+=5){let h=house();h.position.set(x,0,-5)}ui()}
function pick(o){selected=o;tc.attach(o);ui()}
renderer.domElement.addEventListener('pointerdown',e=>{if(e.button!==0)return;let r=renderer.domElement.getBoundingClientRect(),v=new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),ray=new THREE.Raycaster();ray.setFromCamera(v,camera);for(let h of ray.intersectObjects(world.children,true)){let o=h.object;while(o.parent&&o.parent!==world)o=o.parent;if(o.userData.editable){pick(o);break}}});
function ui(){el('fps').textContent='SMART3D · '+objs.length+' objects';el('tree').innerHTML=objs.length?objs.map((o,i)=>`<div class="node ${o===selected?'sel':''}" data-i="${i}">◇ ${o.name}<small>3D</small></div>`).join(''):'<div class="muted" style="padding:15px">Scene empty</div>';document.querySelectorAll('.node').forEach(n=>n.onclick=()=>pick(objs[+n.dataset.i]));if(!selected){el('inspector').textContent='Select an object';return}el('inspector').innerHTML=`<div class="field"><label>Name</label><input id="iname" value="${selected.name}"></div><div class="title" style="padding:5px 0">Transform</div><div class="trip">${['x','y','z'].map(a=>`<div class="field"><label>Pos ${a}</label><input data-p="${a}" type="number" step=".1" value="${selected.position[a].toFixed(2)}"></div>`).join('')}</div><div class="trip">${['x','y','z'].map(a=>`<div class="field"><label>Scale ${a}</label><input data-s="${a}" type="number" step=".1" value="${selected.scale[a].toFixed(2)}"></div>`).join('')}</div><div class="field"><label>Rotation Y</label><input id="ry" type="number" step="1" value="${THREE.MathUtils.radToDeg(selected.rotation.y).toFixed(1)}"></div>`;el('iname').oninput=e=>{selected.name=e.target.value;ui()};document.querySelectorAll('[data-p]').forEach(i=>i.oninput=()=>selected.position[i.dataset.p]=+i.value);document.querySelectorAll('[data-s]').forEach(i=>i.oninput=()=>selected.scale[i.dataset.s]=+i.value);el('ry').oninput=e=>selected.rotation.y=THREE.MathUtils.degToRad(+e.target.value)}
document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{let o=maker[b.dataset.add]();o.position.set((objs.length%4)*3-4.5,0,-Math.floor(objs.length/4)*3)});document.querySelectorAll('[data-location]').forEach(b=>b.onclick=()=>location(b.dataset.location));
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tool]').forEach(x=>x.classList.remove('active'));b.classList.add('active');let t=b.dataset.tool;if(t==='move')tc.setMode('translate');if(t==='rotate')tc.setMode('rotate');if(t==='scale')tc.setMode('scale');el('mode').textContent=t.toUpperCase()});el('delete').onclick=()=>{if(selected){world.remove(selected);objs.splice(objs.indexOf(selected),1);selected=null;tc.detach();ui()}};
el('new').onclick=()=>{clear();ui()};el('save').onclick=()=>{let data={app:'Smart3D',version:1,objects:objs.map(o=>({name:o.name,pos:o.position.toArray(),rot:o.rotation.toArray(),scale:o.scale.toArray()}))};let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='smart3d-scene.json';a.click()};
el('build').onclick=()=>{let s=el('prompt').value.toLowerCase();let loc=['mountain','forest','beach','desert','city','village'].find(x=>s.includes(x))||'mountain';location(loc);let found=Object.keys(maker).filter(x=>new RegExp('\\b'+x+'\\b').test(s));(found.length?found:['man','dog']).forEach((x,i)=>{let o=maker[x]();o.position.set((i%4)*3-4.5,0,Math.floor(i/4)*-3)})};
el('play').onclick=()=>{let on=el('play').textContent==='▶';el('play').textContent=on?'❚❚':'▶';if(on){let start=performance.now();function a(t){if(el('play').textContent!=='❚❚')return;el('playhead').style.left=(12+((t-start)/50)%780)+'px';requestAnimationFrame(a)}requestAnimationFrame(a)}};
async function loadModel(file){new GLTFLoader().load(URL.createObjectURL(file),g=>{g.scene.traverse(o=>{if(o.isMesh)o.castShadow=o.receiveShadow=true});add(g.scene,file.name.replace(/\.(glb|gltf)$/i,''))},undefined,e=>alert(e.message))}el('modelFile').onchange=e=>e.target.files[0]&&loadModel(e.target.files[0]);el('hdrFile').onchange=e=>{let f=e.target.files[0];if(f)new RGBELoader().load(URL.createObjectURL(f),t=>{t.mapping=THREE.EquirectangularReflectionMapping;scene.environment=t;scene.background=t})};
function resize(){let r=host.getBoundingClientRect();camera.aspect=r.width/r.height;camera.updateProjectionMatrix();renderer.setSize(r.width,r.height)}new ResizeObserver(resize).observe(host);resize();location('mountain');human('man').position.set(0,0,0);animal('dog').position.set(3,0,-2);tree().position.set(-4,0,-2);ui();(function loop(){requestAnimationFrame(loop);orbit.update();renderer.render(scene,camera)})();
</script></body></html>
